const payload = $input.item.json || {};
const msg = payload.message || payload.body?.message || payload.payload?.message || {};

const rawText =
  payload.rawText ||
  payload.text ||
  msg.text ||
  payload.payload?.text ||
  '';

const chatId =
  payload.chatId ||
  msg.chat?.id ||
  payload.payload?.chatId ||
  payload.payload?.message?.chat?.id;

function normalize(str) {
  return String(str || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/đ/g, 'd')
    .replace(/Đ/g, 'D')
    .trim();
}

const text = normalize(rawText);

function hasAny(keywords) {
  return keywords.some(k => text.includes(k));
}

let action = 'help';

if (hasAny([
  'drive help',
  'huong dan drive',
  'dung drive nhu the nao',
  'google drive help'
])) {
  action = 'help';

} else if (hasAny([
  'xem drive',
  'xem file drive',
  'file gan day',
  'liet ke file',
  'danh sach file',
  'list drive files',
  'recent files'
])) {
  action = 'list_files';

} else if (hasAny([
  'tim file',
  'search file',
  'kiem file',
  'tim trong drive',
  'find file'
])) {
  action = 'search_file';

} else if (hasAny([
  'thong tin file',
  'chi tiet file',
  'file info',
  'metadata file'
])) {
  action = 'get_file_info';

} else if (hasAny([
  'tao folder',
  'tao thu muc',
  'create folder'
])) {
  action = 'create_folder';

} else if (hasAny([
  'upload file',
  'luu file nay vao drive',
  'luu tep nay vao drive',
  'tai file nay len drive',
  'up file'
])) {
  action = 'upload_file';

} else if (hasAny([
  'download file',
  'tai file',
  'gui toi file',
  'lay file',
  'tai xuong file',
  'send me file'
])) {
  action = 'download_file';

} else if (hasAny([
  'copy file',
  'nhan ban file',
  'tao ban sao file',
  'duplicate file',
  'copy template'
])) {
  action = 'copy_file';

} else if (hasAny([
  'doi ten file',
  'rename file',
  'doi ten thu muc'
]) || /doi ten .+ thanh .+/.test(text)) {
  action = 'rename_file';

} else if (hasAny([
  'di chuyen file',
  'move file',
  'chuyen file',
  'dua file'
])) {
  action = 'move_file';

} else if (hasAny([
  'xoa file',
  'xoa thu muc',
  'delete file',
  'bo file vao thung rac',
  'move file to trash'
])) {
  action = 'delete_file';

} else if (hasAny([
  'share file',
  'chia se file',
  'cap quyen file',
  'give access'
])) {
  action = 'share_file';

} else if (hasAny([
  'xuat file',
  'export file',
  'chuyen file',
  'chuyen doc sang pdf',
  'export sheet'
])) {
  action = 'export_file';

} else if (hasAny([
  'drive',
  'google drive'
])) {
  action = 'list_files';
}

return [{
  json: {
    payload,
    message: msg,
    chatId,
    rawText,
    text,
    action
  }
}];

const workflows = $input.item.json.data || [];
const source = $('Chon Workflow Drive').item.json;
const found = workflows.find((workflow) => workflow.name === source.workflowName);
if (!found) return [{ json: { ...source, hasWorkflow: false, response: 'Khong tim thay workflow con: ' + source.workflowName } }];
return [{ json: { ...source, hasWorkflow: true, workflowId: found.id } }];
